package com.ankit.joblens.batchapi;
import com.ankit.joblens.profile.ResumeProfileService; import org.springframework.http.MediaType; import org.springframework.web.bind.annotation.*; import org.springframework.web.multipart.MultipartFile; import java.util.List;
import io.swagger.v3.oas.annotations.Operation; import io.swagger.v3.oas.annotations.tags.Tag;
@RestController @RequestMapping("/api/candidate-profile") @Tag(name="Candidate profile",description="Read and confirm the candidate profile used for job scoring") public class ResumeProfileController { private final ResumeProfileService service; public ResumeProfileController(ResumeProfileService service){this.service=service;} @GetMapping @Operation(summary="Get current candidate profile",description="Returns the saved profile and skills used by the scoring batch") public Object profile(){return service.profile();} @PutMapping @Operation(summary="Save reviewed skills",description="Replaces the default profile skills after resume review") public Object update(@RequestBody SkillsRequest request){return service.updateSkills(request.skills());} @PostMapping(value="/resume",consumes=MediaType.MULTIPART_FORM_DATA_VALUE) @Operation(summary="Read a resume",description="Extracts PDF/DOCX text, detects catalog skills, and saves them for review") public Object upload(@RequestPart("file") MultipartFile file)throws Exception{return service.readAndApply(file);} public record SkillsRequest(List<String> skills){} }
